def _sandbox(*, pid=-1, name="sb-abc", unattached=True, last_attached=0.0, phase="Ready", cwd=None):
    from claude_dashboard.controller import _SessionEntry
    from claude_dashboard.session import SessionInfo

    entry = _SessionEntry(
        SessionInfo(
            pid=pid,
            session_id=f"sandbox-{name}",
            cwd=cwd or f"/home/u/sandboxes/{name}",
            started_at=0,
            entrypoint="sandbox",
        )
    )
    entry.sandbox = True
    entry.sandbox_phase = phase
    entry.unattached = unattached
    entry.last_attached = last_attached
    return entry


def _sweep(c, *, scan_ok=True):
    with (
        patch("claude_dashboard.controller._now_epoch", return_value=_NOW),
        patch("claude_dashboard.controller.subprocess.Popen") as popen,
    ):
        c._stop_idle_sandboxes(scan_ok=scan_ok)
    return popen


class TestSweep:
    def test_attached_is_stamped_not_stopped(self):
        entry = _sandbox(unattached=False, last_attached=_OLD)
        c = _controller(entry)
        popen = _sweep(c)
        assert entry.last_attached == _NOW
        popen.assert_not_called()
        c._save_session_state.assert_called_once()

    def test_unattached_without_stamp_starts_clock(self):
        entry = _sandbox(last_attached=0.0)
        c = _controller(entry)
        popen = _sweep(c)
        assert entry.last_attached == _NOW
        popen.assert_not_called()

    def test_unattached_within_threshold_not_stopped(self):
        entry = _sandbox(last_attached=_NOW - 60)
        popen = _sweep(_controller(entry))
        popen.assert_not_called()
        assert entry.last_attached == _NOW - 60

    def test_unattached_past_threshold_stopped(self):
        # Covers the reboot case: stamp restored from disk is already old.
        entry = _sandbox(last_attached=_OLD)
        c = _controller(entry)
        popen = _sweep(c)
        popen.assert_called_once()
        assert popen.call_args.args[0] == ["openshell", "sandbox", "stop", "sb-abc"]
        assert "sb-abc" in c._sandbox_stops

    def test_non_ready_not_stopped(self):
        for phase in ("Stopped", "Stopping", "Error", "Creating"):
            popen = _sweep(_controller(_sandbox(last_attached=_OLD, phase=phase)))
            popen.assert_not_called()

    def test_failed_scan_skips_sweep(self):
        attached = _sandbox(pid=-1, name="sb-a", unattached=False, last_attached=_OLD)
        idle = _sandbox(pid=-2, name="sb-b", last_attached=_OLD)
        c = _controller(attached, idle)
        popen = _sweep(c, scan_ok=False)
        popen.assert_not_called()
        assert attached.last_attached == _OLD
        c._save_session_state.assert_not_called()

    def test_non_sandbox_ignored(self):
        entry = _sandbox(last_attached=_OLD)
        entry.sandbox = False
        popen = _sweep(_controller(entry))
        popen.assert_not_called()
        assert entry.last_attached == _OLD


class TestInFlightStops:
    def test_no_second_stop_while_running(self):
        entry = _sandbox(last_attached=_OLD)
        c = _controller(entry)
        running = MagicMock()
        running.poll.return_value = None
        c._sandbox_stops["sb-abc"] = running
        popen = _sweep(c)
        popen.assert_not_called()
        assert c._sandbox_stops["sb-abc"] is running

    def test_finished_stop_is_reaped_and_retried(self):
        # A failed stop leaves the sandbox Ready; the next sweep tries again.
        entry = _sandbox(last_attached=_OLD)
        c = _controller(entry)
        done = MagicMock()
        done.poll.return_value = 1
        c._sandbox_stops["sb-abc"] = done
        popen = _sweep(c)
        popen.assert_called_once()
        assert c._sandbox_stops["sb-abc"] is popen.return_value

    def test_finished_stop_reaped_even_on_failed_scan(self):
        c = _controller()
        done = MagicMock()
        done.poll.return_value = 0
        c._sandbox_stops["sb-gone"] = done
        _sweep(c, scan_ok=False)
        assert c._sandbox_stops == {}

