class TestPersistence:
    def test_last_attached_round_trips(self, tmp_path):
        from claude_dashboard.controller import AppController

        entry = _sandbox(last_attached=_OLD)
        c = _controller(entry)
        c._is_ignored = MagicMock(return_value=False)
        state_file = tmp_path / "session-state.json"
        with patch("claude_dashboard.config.STATE_FILE", state_file):
            AppController._save_session_state(c)
        saved = json.loads(state_file.read_text())
        assert saved[entry.session.cwd]["last_attached"] == _OLD

        fresh = _sandbox()
        c._saved_state = saved
        c._apply_saved_state(fresh)
        assert fresh.last_attached == _OLD

